fn all_characters_same(char_arr: &Vec<char>) -> bool {
    // If there are zero or one elements, the condition holds vacuously
    if char_arr.len() <= 1 {
        return true;
    }
    // Grab the first character
    let first = char_arr[0];
    // Check that every subsequent character equals the first
    char_arr.iter().skip(1).all(|&c| c == first)
}